#### Phase 2: Enforcement Mechanisms

**Week 5-6: Repository Structure**

7. **Implement Repository Isolation**:
   ```bash
   # Repository Restructuring Script

   #!/bin/bash
   # migrate-to-ip-structure.sh

   echo "Restructuring repository for IP isolation..."

   # Create IP-based directory structure
   mkdir -p src/extensions/exclusive
   mkdir -p src/extensions/restricted
   mkdir -p src/extensions/shared
   mkdir -p src/extensions/contributable

   # Move existing customizations to appropriate directories
   # (requires manual review of each customization)

   echo "Review required: Classify each customization"
   echo "Then run: ./classify-and-move.sh"
   ```

8. **Configure Access Controls**:
   ```yaml
   # GitHub/Azure DevOps CODEOWNERS file

   # Product code - all product team
   /src/product/ @gainwell/product-team

   # Shared extensions - extension team
   /src/extensions/shared/ @gainwell/extension-team

   # Contributable - extension team + product team review
   /src/extensions/contributable/ @gainwell/extension-team @gainwell/product-team

   # State-specific exclusive code
   /src/extensions/exclusive/florida/ @gainwell/florida-team
   /src/extensions/exclusive/texas/ @gainwell/texas-team
   /src/extensions/exclusive/pennsylvania/ @gainwell/pennsylvania-team

   # Legal team has read access to all IP metadata
   /**/ip-metadata.yaml @gainwell/legal-team
   ```

**Week 7-8: Build-Time Validation**

9. **Implement IP Validation Tool**:
   ```csharp
   // IPValidationTool.cs - CI/CD Pipeline Integration

   public class IPValidationTool
   {
       private readonly IIPClassificationRegistry _registry;

       public async Task<ValidationReport> ValidateSolutionAsync(string solutionPath)
       {
           var report = new ValidationReport();
           var solution = await LoadSolutionAsync(solutionPath);

           foreach (var project in solution.Projects)
           {
               // Validate IP metadata exists
               if (!project.HasIPMetadata())
               {
                   report.AddWarning(project.Name,
                       "Missing IP classification metadata");
                   continue;
               }

               var metadata = await project.LoadIPMetadataAsync();
               var classification = await _registry.GetClassificationAsync(
                   metadata.CustomizationId);

               // Validate classification matches registry
               if (metadata.Category != classification.Category)
               {
                   report.AddError(project.Name,
                       $"Classification mismatch: Local={metadata.Category}, " +
                       $"Registry={classification.Category}");
               }

               // Validate dependencies respect IP boundaries
               await ValidateDependenciesAsync(project, classification, report);
           }

           return report;
       }

       private async Task ValidateDependenciesAsync(
           Project project,
           IPClassification classification,
           ValidationReport report)
       {
           foreach (var dependency in project.ProjectReferences)
           {
               var depMetadata = await dependency.LoadIPMetadataAsync();
               var depClassification = await _registry.GetClassificationAsync(
                   depMetadata.CustomizationId);

               // Rule: Exclusive cannot depend on Shared/Contributable
               if (classification.Category == "exclusive" &&
                   (depClassification.Category == "shared" ||
                    depClassification.Category == "contributable"))
               {
                   report.AddError(project.Name,
                       $"Exclusive project cannot reference {depClassification.Category} " +
                       $"project: {dependency.Name}");
               }

               // Rule: Shared cannot depend on Exclusive
               if (classification.Category == "shared" &&
                   depClassification.Category == "exclusive")
               {
                   report.AddError(project.Name,
                       $"Shared project cannot reference exclusive project: " +
                       $"{dependency.Name}");
               }

               // Rule: Cross-state exclusive references not allowed
               if (classification.Category == "exclusive" &&
                   depClassification.Category == "exclusive" &&
                   classification.CustomerState != depClassification.CustomerState)
               {
                   report.AddError(project.Name,
                       $"Cannot reference exclusive code from different state: " +
                       $"{depClassification.CustomerState}");
               }
           }
       }
   }
   ```

10. **Integrate into CI/CD**:
    ```yaml
    # Azure DevOps Pipeline - IP Validation

    - task: PowerShell@2
      displayName: 'Validate IP Classifications'
      inputs:
        targetType: 'inline'
        script: |
          dotnet run --project tools/IPValidationTool/IPValidationTool.csproj `
            -- validate --solution $(Build.SourcesDirectory)/GainwellSolution.sln `
            --report $(Build.ArtifactStagingDirectory)/ip-validation-report.json

          if ($LASTEXITCODE -ne 0) {
            Write-Error "IP Validation failed. Check report for details."
            exit 1
          }

    - task: PublishBuildArtifacts@1
      condition: always()
      displayName: 'Publish IP Validation Report'
      inputs:
        PathtoPublish: '$(Build.ArtifactStagingDirectory)/ip-validation-report.json'
        ArtifactName: 'ip-validation-reports'
    ```
